import * as THREE from 'three';
import { CONFIG } from '../../config';
import { MAT } from '../../core/materials';
import { shared, weatherU } from '../../core/shared';
import { cableSag } from './impact';
import type { WeatherParams } from './state';

/* ===== [weather] Nắng hè (mục 4.7): 0 draw call, chỉ shader + uniform =====
   - Ảo ảnh mặt đường: vá MAT.road, MAT.road2 (đường phố) — nhìn sát mặt (|cos| tia nhìn–pháp tuyến nhỏ) và xa hơn mirageNear thì trộn màu sương (fogColor)
     và dao động nhẹ UV theo uTime. Cường độ = uHaze × (1 − đêm). Không dùng pass hậu kỳ. uHaze = 0 → nhánh không chạy (ảnh preset `now` không đổi).
     Mặt cầu có vật liệu riêng (bridgePatch) nên chưa có ảo ảnh — chỉ đường phố.
   - Võng cáp phóng đại: uSagTp = Δf (cableSag, m) × swayExaggeration, đọc bởi option `sag` của bridgePatch (cáp chủ + đầu trên hanger Thuận Phước).
   Grade màu hè (hemi ấm, sương be, nước xanh ngọc) nằm ở atmosphere.ts (GĐ2). */
const f = (x: number) => x.toFixed(4);

function patchMirage(mat: THREE.MeshStandardMaterial, key: string) {
  const S = CONFIG.weather.summer;
  mat.customProgramCacheKey = () => key;
  mat.onBeforeCompile = (sh) => {
    sh.uniforms.uTime = shared.uTime; sh.uniforms.uNight = shared.uNight; sh.uniforms.uHaze = weatherU.uHaze;
    const mapChunk = THREE.ShaderChunk.map_fragment.replace('texture2D( map, vMapUv )', 'texture2D( map, vMapUv + mgOff )');
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform float uTime; uniform float uNight; uniform float uHaze;')
      .replace('#include <map_fragment>', `
        vec2 mgOff = vec2(0.0); float mgK = 0.0;
        if (uHaze > 0.0) {
          vec3 mgV = normalize(vViewPosition), mgUp = normalize((viewMatrix * vec4(0.0, 1.0, 0.0, 0.0)).xyz);
          float mgD = length(vViewPosition);
          mgK = uHaze * (1.0 - uNight) * (1.0 - smoothstep(0.0, ${f(S.mirageGraze)}, abs(dot(mgV, mgUp)))) * smoothstep(${f(S.mirageNear)}, ${f(S.mirageFar)}, mgD);
          mgOff = vec2(sin(uTime * ${f(S.mirageFreq)} + vViewPosition.x * 0.31), cos(uTime * ${f(S.mirageFreq * 1.3)} + vViewPosition.z * 0.27)) * ${f(S.mirageWobble)} * mgK;
        }
        ${mapChunk}
        if (mgK > 0.0) diffuseColor.rgb = mix(diffuseColor.rgb, fogColor + vec3(${f(S.mirageLift)}), mgK * ${f(S.mirageMix)});`);
  };
  mat.needsUpdate = true;
}

/* Gọi trong buildWeather, trước khung hình đầu (vật liệu chưa biên dịch) */
export function buildSummer() {
  patchMirage(MAT.road, 'road-mirage');
  patchMirage(MAT.road2, 'road2-mirage');
}

/* Mỗi khung: võng cáp phóng đại. on = weather đang bật; nhiệt độ chuẩn → đúng 0 */
export function updateSummer(c: WeatherParams, on: boolean) {
  const sag = on ? cableSag(c.temp) * CONFIG.weather.swayExaggeration : 0;
  weatherU.uSagTp.value = Math.abs(sag) < 1e-4 ? 0 : sag;
}
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { MAT } from '../../core/materials';

/* ===== [weather] Mặt ướt (mục 4.4): 0 draw call, chỉ đổi thuộc tính vật liệu =====
   Vật liệu "đường" đăng ký TƯỜNG MINH bằng registerWet() (không dò theo tên). Theo `wet`: roughness lerp từ gốc về wetness.roughness,
   màu nhân wetness.darken (đường ướt sẫm, phản chiếu đèn rõ hơn). Giá trị gốc chụp lúc đăng ký; wet ≈ 0 thì trả ĐÚNG gốc một lần rồi không đụng.
   Bê tông/thép cầu: option `weather` của bridgePatch đọc weatherU.uWet trong shader (common/shaders.ts). */
export type WetKind = 'road';
interface WetEntry { mat: THREE.MeshStandardMaterial; kind: WetKind; roughness: number; color: THREE.Color }
const list: WetEntry[] = [];
let active = false;

export function registerWet(mat: THREE.MeshStandardMaterial, kind: WetKind = 'road') {
  if (list.some((e) => e.mat === mat)) return mat;
  list.push({ mat, kind, roughness: mat.roughness, color: mat.color.clone() });
  return mat;
}
export const wetMaterials = () => list.map((e) => e.mat);

/* Đường chung của cảnh (phố, vỉa hè, kè đá). Đường của từng cầu tự đăng ký trong materials.ts của cầu đó */
export function buildWetness() {
  for (const m of [MAT.road, MAT.road2, MAT.paver, MAT.stone]) registerWet(m);
}

export function applyWetness(wet: number) {
  if (wet < 1e-3) {
    if (active) { for (const e of list) { e.mat.roughness = e.roughness; e.mat.color.copy(e.color); } active = false; }
    return;
  }
  active = true;
  const W = CONFIG.weather.wetness, k = Math.min(1, wet), dark = 1 - (1 - W.darken) * k;
  for (const e of list) { e.mat.roughness = e.roughness + (W.roughness - e.roughness) * k; e.mat.color.copy(e.color).multiplyScalar(dark); }
}
/* Uniform dùng chung cho mọi hiệu ứng LED / cửa sổ đêm */
export const shared = { uTime: { value: 0 }, uNight: { value: 0 } };
/* Hệ số cỡ hạt lửa / nước theo chiều cao khung hình (cập nhật khi đổi kích thước) */
export const pScale = { value: 1 };
/* Uniform thời tiết (mặt ướt, mưa, gió, mù nóng, hệ số lắc). TÁCH khỏi `shared` vì MAT.ledRail dùng nguyên object `shared` làm uniforms.
   Mặc định 0 = không đổi gì; chỉ weather/index.ts ghi vào.
   Gió (GĐ4): uWindDir = hướng gió thổi tới (cos, sin) trên mặt XZ; biên độ lắc ĐÃ nhân hệ số phóng đại (m): uSwayTp (hanger TP),
   uSwayTtl (dây văng TTL, đường cong mưa–gió), uSwaySh (dây văng Cầu sông Hàn); uTreeLean / uTreeSway: độ nghiêng tĩnh / dao động tán cây (m dịch trên mỗi m cao). */
export const weatherU = {
  uWet: { value: 0 }, uRain: { value: 0 }, uWind: { value: 0 }, uGust: { value: 0 }, uHaze: { value: 0 }, uSwayK: { value: 0 },
  uWindDir: { value: [1, 0] }, uSwayTp: { value: 0 }, uSwayTtl: { value: 0 }, uSwaySh: { value: 0 }, uTreeLean: { value: 0 }, uTreeSway: { value: 0 },
  uSagTp: { value: 0 }   // GĐ7: võng thêm của cáp chủ Thuận Phước khi nóng (m, ĐÃ nhân phóng đại); 0 = không đổi gì
};
/* Hệ số gió cho code CPU (thuyền, lửa/nước Cầu Rồng, râu rồng, sóng). Mặc định trung tính: x = z = 0, nhân 1 → không đổi hành vi. */
export const windFx = { x: 0, z: 0, boatRock: 1, whisker: 1, waveSpeed: 1 };
/* Vận hành theo thời tiết (GĐ5), mặc định trung tính: clear = tiến độ dọn xe khi đóng cầu (0–1); boatAway = tiến độ thuyền về bến (0–1);
   showAllowed = trình diễn Cầu Rồng được chạy; swingBlocked = khoá quay Cầu sông Hàn; wheelStopped = Vòng quay Mặt Trời dừng (GĐ6). KHÔNG đụng nút người dùng (lifeOn, show.on, quảng cáo). */
export const weatherFx = { clear: 0, boatAway: 0, showAllowed: true, swingBlocked: false, wheelStopped: false };
/* Phương tiện thứ i đã biến mất chưa khi tiến độ k (thứ tự cố định theo i, không dùng rand()): k = 0 → không ai, k = 1 → tất cả */
export const vanished = (i: number, k: number) => k > 0 && (i * 0.6180339887) % 1 < k;
import * as THREE from 'three';
