// Kiểm một lần (Task 8 D-040, không commit): chụp góc cũ ở ?test với thời gian đóng băng + Math.random có seed,
// đọc renderer.info.programs.length. Dùng: node tests/road-identity.mjs <thư mục dist> <tiền tố ảnh>
import { fileURLToPath } from 'node:url';
import { mkdirSync, writeFileSync } from 'node:fs';
import { serveDir, launch, openApp, frames } from './lib.mjs';

const [dir, tag] = process.argv.slice(2);
const SCREENS = fileURLToPath(new URL('./screens/', import.meta.url));
mkdirSync(SCREENS, { recursive: true });
const srv = await serveDir(dir), browser = await launch();
const freeze = () => {
  let s = 12345; Math.random = () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
  const T = 1e6; performance.now = () => T; Date.now = () => 1.7e12;
};
const { page, errors } = await openApp(browser, srv.url, { width: 640, height: 360, before: (p) => p.addInitScript(freeze) });
await frames(page, 6);
const views = [
  ['default', null],
  ['street', { p: [330, 4.2, 6], t: [380, 2.6, 4] }],          // đường bờ Đông nối Cầu Rồng (MAT.road)
  ['deck-sh', { p: [-60, 12, -1076], t: [-10, 9, -1078] }],      // mặt Cầu sông Hàn
  ['deck-ttl', { p: [-80, 14, 1296], t: [-30, 12, 1300] }]       // mặt Trần Thị Lý
];
const out = {};
for (const [name, v] of views) {
  if (v) await page.evaluate((v) => { const a = window.__app; a.cam.mode = 'orbit'; a.camera.position.set(...v.p); a.controls.target.set(...v.t); a.controls.update(); }, v);
  await frames(page, 4);
  await page.screenshot({ path: `${SCREENS}${tag}-${name}.png` });
  out[name] = await page.evaluate(() => window.__app.renderer.info.programs.length);
}
out.errors = errors;
writeFileSync(`${SCREENS}${tag}.json`, JSON.stringify(out, null, 1));
console.log(tag, JSON.stringify(out));
await browser.close(); srv.close();

