// Một lần (Task 8, không commit): liệt kê program dùng chung với vật liệu đường
import { serveDir, launch, openApp, frames } from './lib.mjs';
const [dir] = process.argv.slice(2);
const srv = await serveDir(dir), browser = await launch();
const freeze = () => { let s = 12345; Math.random = () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; performance.now = () => 1e6; Date.now = () => 1.7e12; };
const { page } = await openApp(browser, srv.url, { width: 640, height: 360, before: (p) => p.addInitScript(freeze) });
await frames(page, 6);
