// Ảnh xem tay Task 8 D-040 (không commit): góc thứ nhất trên phố + mặt cầu, khô ban ngày / ướt ban đêm, A/B uRoadNear 1 / 0, hai khung khi đang chạy.
// Dùng: npm run build && node tests/bike-road-shots.mjs
import { fileURLToPath } from 'node:url';
import { mkdirSync } from 'node:fs';
import { serveDir, launch, openApp, frames } from './lib.mjs';
import { setWx } from './weather-lib.mjs';

const SCREENS = fileURLToPath(new URL('./screens/', import.meta.url));
mkdirSync(SCREENS, { recursive: true });
const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url))), browser = await launch();
const { page, errors } = await openApp(browser, srv.url + '?explore=bike', { width: 960, height: 540 });
await page.waitForFunction(() => window.__app.bike.active(), null, { timeout: 120000 });
await frames(page, 4);
const info = { near: await page.evaluate(() => window.__app.shared.uRoadNear.value) };
const spots = [['street', 300, 4.5, 0], ['deck', -60, 1302, 0]];
const shot = async (name) => { await frames(page, 3); await page.screenshot({ path: `${SCREENS}${name}.png` }); };
const at = (x, z, yaw) => page.evaluate(([x, z, yaw]) => window.__app.bike.placeAt(x, z, yaw), [x, z, yaw]);
const setNear = (v) => page.evaluate((v) => { window.__app.shared.uRoadNear.value = v; }, v);
for (const wn of [false, true]) {
  if (wn) { await setWx(page, 'rain'); await page.evaluate(() => { const d = window.__app.dayNight; d.target = 1; d.night = 1; }); await frames(page, 4); }
  const tag = wn ? 'wet-night' : 'dry';
  for (const [s, x, z, yaw] of spots) {
    await at(x, z, yaw);
    await shot(`bike-road-${tag}-${s}`);
    await setNear(0); await shot(`bike-road-${tag}-${s}-off`); await setNear(1);
  }
  /* hai khung khi đang chạy 10 m/s: dịch 0,2 m rồi 0,4 m */
  for (const d of [0.2, 0.4]) { await at(300 + d, 4.5, 0); await shot(`bike-road-${tag}-move${d}`); }
}
await page.evaluate(() => window.__app.bike.placeAt(300, 4.5, 0));
await setWx(page, 'rain'); await shot('bike-road-wet-night');
await page.evaluate(() => { const d = window.__app.dayNight; d.target = 0; d.night = 0; window.__app.weather.setPreset('now'); }); await setWx(page, 'now'); await shot('bike-road-dry');
info.programs = await page.evaluate(() => window.__app.renderer.info.programs.length);
info.errors = errors;
console.log(JSON.stringify(info));
await browser.close(); srv.close();

