// Một lần (Task 8, không commit): so điểm ảnh từng cặp PNG. node tests/png-diff.mjs a1.png b1.png [a2.png b2.png ...]
import { readFileSync } from 'node:fs';
import { chromium } from 'playwright';
const files = process.argv.slice(2), browser = await chromium.launch(), page = await browser.newPage();
for (let i = 0; i < files.length; i += 2) {
  const [a, b] = [files[i], files[i + 1]].map((f) => 'data:image/png;base64,' + readFileSync(f).toString('base64'));
  const r = await page.evaluate(async ([a, b]) => {
    const load = (s) => new Promise((ok) => { const im = new Image(); im.onload = () => ok(im); im.src = s; });
    const [A, B] = await Promise.all([load(a), load(b)]);
    const px = (im) => { const c = document.createElement('canvas'); c.width = im.width; c.height = im.height; const g = c.getContext('2d'); g.drawImage(im, 0, 0); return g.getImageData(0, 0, im.width, im.height).data; };
    const pa = px(A), pb = px(B); let n = 0, max = 0, sum = 0;
    for (let k = 0; k < pa.length; k += 4) { const d = Math.max(Math.abs(pa[k] - pb[k]), Math.abs(pa[k + 1] - pb[k + 1]), Math.abs(pa[k + 2] - pb[k + 2])); if (d) n++; max = Math.max(max, d); sum += d; }
    return { changed: n, total: pa.length / 4, max, mean: sum / (pa.length / 4) };
  }, [a, b]);
  console.log(files[i].split(/[\\/]/).pop(), 'vs', files[i + 1].split(/[\\/]/).pop(), JSON.stringify(r));
}
await browser.close();

